function createDebouncedAsync(fn, delay) {
  let timeoutId = null;
  let abortController = null;

  const debouncedFn = async (...args) => {
    // Clear any existing timeout
    if (timeoutId) {
      clearTimeout(timeoutId);
    }

    // Abort any pending request
    if (abortController) {
      abortController.abort();
    }

    // Create new abort controller
    abortController = new AbortController();

    return new Promise((resolve, reject) => {
      timeoutId = setTimeout(async () => {
        try {
          // Pass the abort signal to the async function
          const result = await fn(...args, { signal: abortController.signal });
          resolve(result);
        } catch (error) {
          // Don't reject if the request was aborted
          if (error.name === 'AbortError') {
            resolve(undefined);
          } else {
            reject(error);
          }
        } finally {
          abortController = null;
          timeoutId = null;
        }
      }, delay);
    });
  };

  debouncedFn.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
    }
    if (abortController) {
      abortController.abort();
      abortController = null;
    }
  };

  return debouncedFn;
}

