/// Safely parses a string into an i32, handling overflow and invalid input
/// Returns None if parsing fails or if the number overflows i32
fn safe_parse_i32(input: &str) -> Option<i32> {
    // First, try parsing as i64 to detect overflow
    match input.parse::<i64>() {
        Ok(value) => {
            // Check if the value fits in i32
            if value >= i32::MIN as i64 && value <= i32::MAX as i64 {
                Some(value as i32)
            } else {
                None // Overflow occurred
            }
        }
        Err(_) => None, // Invalid input
    }
}

